-- Image Generation styles (owner decision, 2026-11-04): a preset belongs to Create (`video`, a motion preset) or Image Generation (`image`, a style
-- whose prompt is added to the member's own). A proposal carries its preset's feature, so a new one lands on the page it was proposed from.
-- The eight styles start without an example image; a template editor uploads one in the picker as samples/preset-<id>.jpg.
ALTER TABLE "preset_proposals" ADD COLUMN "feature" text DEFAULT 'video' NOT NULL;--> statement-breakpoint
ALTER TABLE "presets" ADD COLUMN "feature" text DEFAULT 'video' NOT NULL;--> statement-breakpoint
ALTER TABLE "preset_proposals" ADD CONSTRAINT "preset_proposals_feature_check" CHECK ("preset_proposals"."feature" in ('video', 'image'));--> statement-breakpoint
ALTER TABLE "presets" ADD CONSTRAINT "presets_feature_check" CHECK ("presets"."feature" in ('video', 'image'));--> statement-breakpoint
