INSERT INTO "presets" ("id", "label", "prompt", "enabled", "sort_order", "feature") VALUES
	('style-white-studio', U&'Studio n\1ec1n tr\1eafng', 'Clean white seamless studio background with soft, even, nearly shadowless light, like a professional e-commerce photo. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 1, 'image'),
