	('style-pastel-minimal', U&'T\1ed1i gi\1ea3n pastel', 'Minimal set in soft pastel colours with a few simple geometric props and soft, diffused shadows. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 4, 'image'),
	('style-golden-hour', U&'Ngo\00e0i tr\1eddi gi\1edd v\00e0ng', 'Outdoors at golden hour, with warm, low sunlight, a soft glow and a gently blurred natural background. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 5, 'image'),
	('style-street', U&'\0110\01b0\1eddng ph\1ed1', 'Urban street scene with a candid, documentary feel, natural city light and a softly blurred street behind. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 6, 'image'),
	('style-dark-luxury', U&'Sang tr\1ecdng t\1ed1i', 'Dark luxury setting on a deep, near-black background, with low-key lighting and a subtle rim light that outlines the subject. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 7, 'image'),
	('style-flat-lay', U&'Ph\1eb3ng n\1eb1m', 'Flat lay shot from directly above on a clean, styled surface, with the items neatly arranged and soft, even light. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 8, 'image');
